\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
\definecolor{rustred}{rgb}{0.784,0.392,0.149}
\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

\begin{document}
\pagestyle{empty} %% IMPORTANT
\begin{tikzpicture}

	\begin{axis}[
	legend cell align={left},
	tick label style={font=\footnotesize},
	label style={font=\small},
	legend pos=outer north east,
	legend style={font=\footnotesize},
	tick style={draw=black, thick},
	axis line style = thick,
	axis y line = middle,
	axis x line = middle,
	axis equal,
	%grid = both,
	xmin = -1.5,
	xmax = 1.9,
	ymin = -0.9,
	ymax = 2.5,
	xtick = {1},
	ytick = {0},
	xlabel = {$x$},
	ylabel = {$y$},
	xlabel style={below right},
	ylabel style={above left},
	every axis x label/.style={
	at={(ticklabel* cs:1.02)},anchor=west,},
	every axis y label/.style={at={(ticklabel* cs:1.02)}, anchor=south,}
	]

	% Dotted
	\addplot [domain=-1.0:2, samples=100, rustred, dotted, line width=0.75pt, opacity=0.5,
		line width=1pt,	smooth, variable=\x]({\x},{-\x^2+2*\x+1});
	%\addlegendentry{$y=-x^2+2x+1$}
\node[label={[label distance=-5mm,text depth=-1ex, rustred, rotate=0]0:{\small{$y=-x^2+2x+1$}}}, inner sep=1.5pt] at (axis cs:-1.5, 0.8) {}; 
	\addplot [domain=-1:2, samples=100, deepskyblue, dotted, line width=0.75pt, opacity=0.5,
		line width=1pt,	smooth, variable=\x]({\x},{\x^2+1});
	%\addlegendentry{$y=x^2+1$}
\node[label={[label distance=-5mm,text depth=-1ex,  deepskyblue, rotate=0]0:{\small{$y=x^2+1$}}}, inner sep=1.5pt] at (axis cs:0.8, 1.2) {}; 

	% Solid
	\addplot [domain=0:1, samples=100, rustred, solid,
		line width=1pt,	smooth, variable=\x]({\x},{-\x^2+2*\x+1}); 
	\addplot [domain=0:1, samples=100, deepskyblue, solid,
		line width=1pt,	smooth, variable=\x]({\x},{\x^2+1});

	\begin{scope}
		\addplot [name path=f, domain=0:1, samples=100, rustred, solid,
			draw=none, line width=1pt, smooth, variable=\x]
			({\x},{-\x^2+2*\x+1});
		\addplot [name path=g, domain=0:1, samples=100,
			draw=none, line width=1pt, smooth, variable=\x]
			({\x},{\x^2+1}); 
	    \addplot[rustred!40!white, fill opacity=0.5] fill between [of=f and g]; 
    \end{scope}		 	

	% Rot
	\coordinate[] (O) at (axis cs:0,2.2);
	\draw[-, thin, black, dotted] (O) ++(60:4mm and 1.3mm) 
		arc (60:120:4mm and 1.3mm);
	\draw[->, thick, black, solid] (O) ++(60:4mm and 1.3mm) 
		arc (60:-240:4mm and 1.3mm);

	% Arrows
	\draw[->, line width=1pt, solid] (axis cs:0.5,0.9) -- (axis cs:0.5,2.0); 	
	\node[circle, draw=none, fill=deepskyblue, inner sep=1.2pt] at (axis cs:0.5,1.25) {};	
	\node[circle, draw=none, fill=rustred, inner sep=1.2pt] at (axis cs:0.5,1.75) {};	

	\draw[dashed, thin, opacity=0.5] (axis cs:1,0.0) -- (axis cs:1,2); 

	\end{axis}
\end{tikzpicture}
\end{document}

